from pathlib import Path
import json,shutil,hashlib,os,importlib.util
from PIL import Image
D=Path(__file__).resolve().parent;R=D.parents[2]
data=json.loads((D/'producao.json').read_text(encoding='utf-8'))
P=R/'art/creatures/rabbito-family-v1/velocista-relampago/concept-v1'
P.mkdir(parents=True,exist_ok=True)
def write(p,t):p.write_text(t,encoding='utf-8')
def dump(p,v):write(p,json.dumps(v,ensure_ascii=False,indent=2)+'\n')
def rel(p,b):return os.path.relpath(p,b).replace('\\','/')
shutil.copy2(data['source'],P/'concept.png')
shutil.copy2(data['user_reference'],D/'referencia-fornecida.png')
write(P/'prompt.txt',data['prompt']+'\n')
review='Dois braços e duas pernas em salto diagonal; uma perna estendida e outra recolhida. Duas orelhas longas de membrana com varetas douradas e nós claros. Máscara marinho/turquesa com aberturas separadas, esclera, íris azuis e sobrancelha inclinada; focinho leporino exposto. A rabiola dourada nasce no quadril, faz curva longa atrás e possui três laços turquesa/marfim. Raios azuis legíveis junto aos antebraços, calcanhares e abas do quadril. Proteção parcial deixa o corpo marfim visível. Mão distante está em gesto curvado, com dedos sobrepostos; uma vista de modelo futura deve resolver a anatomia oculta. Margem superior estreita na ponta de uma orelha, sem corte visível. Acabamento em cor chapada, sem render metálico realista.\n\nA figura preserva rosto de criatura, mas a postura e a roupagem são deliberadamente mais humanoides que o Arauto. O efeito elétrico é parte do concept, não habilidade implementada. Não há verso, recortes, animação, rig ou pixel art em grade técnica certificados.'
write(P/'brief.md','# Rabbito — Velocista Relâmpago\n\n## Definido pelo autor\n\nEvolução adulta rápida, com raios azuis saindo da armadura/roupagem, cauda comprida, máscara ou capacete, olhos zangados evidentes, orelhas longas e pose de ação. Referência fornecida pelo autor foi analisada como organização de gesto, proteção segmentada e energia que sai das peças; não foi anexada à geração.\n\n## Identidade própria\n\nBase atual: Rabbito creme/turquesa/dourado e orelhas-pipa; rabiola com três laços. A família tem concepts aprovados em ESTILO-APROVADO.md. Esta proposta nova preserva esse parentesco e não substitui o Arauto da Tempestade ou outro design aprovado. Não inventa uma origem anterior à criação por Kael.\n\n## Proposta\n\nNome descritivo provisório: Velocista Relâmpago. Adulto, IV Pandorga, alternativa visual de velocidade. Verbo: interceptar mudando de direção no ar. Pernas de impulsão e rabiola longa contrabalançam a mudança; orelhas recolhidas alinham o gesto. Máscara acompanha focinho leporino em vez de crânio dracônico; paleta creme/turquesa/marinho, dourado estrutural e raios azuis.\n\n## Conferência\n\n'+review+'\n\n## Desconhecido\n\nNome definitivo, posição na árvore, requisito, elemento de gameplay, custos, poderes e integração. Conexão com Rastro dos Ventos é hipótese documental.\n')
write(P/'revisao.md','# Conferência do concept\n\n'+review+'\n\nDesign proposto, aguardando avaliação do autor. Adultos e rigs anteriores preservados.\n')
with Image.open(P/'concept.png') as im:meta=dict(width=im.width,height=im.height,mode=im.mode,alpha_extrema=im.getextrema()[-1] if im.mode=='RGBA' else None)
dump(P/'manifest.json',dict(id='rabbito-velocista-relampago',family_id='rabbito',name='Velocista Relâmpago (proposta)',date=data['date'],stage=4,decision_status='proposed',production_status='concept',implementation_status='not_integrated',tool='image_gen.imagegen',source=data['source'],sha256=hashlib.sha256((P/'concept.png').read_bytes()).hexdigest(),prompt='prompt.txt',references=[dict(path=rel(R/'art/soulgen/keys/rabbito/color-rig-v2/concept.png',P),role='Identidade da base própria'),dict(path=rel(R/'art/creatures/rabbito-family-v1/arauto-da-tempestade/concept-v2/concept.png',P),role='Acabamento próprio aprovado; não copiar anatomia')],external_reference=dict(path=rel(D/'referencia-fornecida.png',P),role='Estudo visual fornecido pelo autor; não usado como input de geração; crédito visível na imagem, autoria não verificada.'),**meta))
old=json.loads((R/'documentation/creatures/rabbito-chart-v2/chart.json').read_text(encoding='utf-8'))
nodes=[]
for ident in ['rabbito','rastro-dos-ventos']:
    node=next(n.copy() for n in old['nodes'] if n['id']==ident)
    for key in ['art','brief']:
        node[key]=rel((R/'documentation/creatures/rabbito-chart-v2'/node[key]).resolve(),D)
    nodes.append(node)
nodes.append(dict(id='rabbito-velocista-relampago',name='Velocista Relâmpago (proposta)',kind='stage',stage=4,identity='Adulto leporino de máscara aberta nos olhos, impulsão diagonal, rabiola longa de três laços e raios azuis.',story='Aprende a mudar a trajetória sem perder o parceiro que precisa alcançar; história interpretativa, não incorporada à bíblia.',decision_status='proposed',production_status='concept',art=rel(P/'concept.png',D),brief=rel(P/'brief.md',D)))
chart=dict(family_id='rabbito',scope='Estudo de alternativa adulta rápida; não substitui o chart aprovado ou integra poderes.',nodes=nodes,edges=[dict(**{'from':'rabbito','to':'rastro-dos-ventos'},kind='reweaving',reason='Relação documental existente de mobilidade, requisitos ainda propostos.',decision_status='proposed'),dict(**{'from':'rastro-dos-ventos','to':'rabbito-velocista-relampago'},kind='reweaving',reason='Hipótese: o salto preciso se transforma em interceptação com mudança rápida de direção. Caminho e requisito não definidos pelo autor.',decision_status='proposed')])
dump(D/'chart.json',chart)
spec=importlib.util.spec_from_file_location('v',R/'.agents/skills/soulmonsters-charts/scripts/validar_chart.py');v=importlib.util.module_from_spec(spec);spec.loader.exec_module(v)
errors=v.validate(chart,D);assert not errors,errors
dump(D/'validacao.json',dict(chart_errors=errors,concept_exists=True,sha256=hashlib.sha256((P/'concept.png').read_bytes()).hexdigest(),visual_review='Imagem aberta após geração; contagem de membros, raiz/rabiola e face conferidas. Sem movimento ou rig.'))
write(D/'CHART.md','# Alternativa adulta rápida do Rabbito\n\n[Concept]('+rel(P/'concept.png',D)+') · [Brief]('+rel(P/'brief.md',D)+') · [Conferência]('+rel(P/'revisao.md',D)+').\n\nProposta: Rabbito → Rastro dos Ventos → Velocista Relâmpago. O adulto rápido foi pedido pelo autor; nome e conexão exata continuam propostas. Arauto da Tempestade e as demais artes aprovadas preservados.\n')
write(D/'index.html','<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rabbito · adulto rápido</title><style>body{margin:0;background:#142834;color:#eee9df;font:18px/1.6 system-ui}main{max-width:1100px;margin:auto;padding:32px 24px}img{width:100%;height:auto}a{color:#83dfe4}a:focus-visible{outline:3px solid gold;outline-offset:5px}</style><main><h1>Rabbito — Velocista Relâmpago</h1><p>Alternativa adulta proposta: máscara com olhos expostos, orelhas longas, rabiola de três laços e descargas azuis nas proteções e roupagem.</p><a href="'+rel(P/'concept.png',D)+'"><img src="'+rel(P/'concept.png',D)+'" alt="Soulmonster leporino adulto em arrancada diagonal, com armadura turquesa, longa cauda dourada de três laços e raios azuis"></a><p><a href="'+rel(P/'brief.md',D)+'">Brief</a> · <a href="'+rel(P/'revisao.md',D)+'">Conferência</a> · <a href="CHART.md">Relação proposta</a></p><p>Nome e posição na árvore ainda propostos. Concepts aprovados anteriores preservados.</p></main></html>')
print('Concept salvo; três nós e duas relações propostas validados; adultos anteriores preservados.')
